window.__CARDFORGE_COVERS__ = [
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
  "data:image/png;base64,",
];

(function () {
  const canvas = document.getElementById('idCanvas');
  const ctx = canvas.getContext('2d');
  // High-res internal render target for crisp export; CSS controls the on-screen size.
  const W = canvas.width, H = canvas.height;

  const state = {
    coverIndex: 0,
    coverImg: null,
    photoImg: null,
    name: '',
    dob: '',
    loc: '',
    sig: '',
    serial: genSerial(),
    textColor: '#f2efe8',
    // photo pan/zoom, normalized: -1..1 offset, zoom 1 = cover-fit
    photoZoom: 1,
    photoOffsetX: 0,
    photoOffsetY: 0,
    // cover art pan/zoom, same convention, tracked per-cover below
    coverZoom: 1,
    coverOffsetX: 0,
    coverOffsetY: 0
  };

  const covers = window.__CARDFORGE_COVERS__ || [];
  const loadedCovers = [];
  // per-cover saved pan/zoom, keyed by cover index, so switching covers
  // restores whatever the user last set for that cover
  const coverTransforms = {};

  function defaultCoverZoom(img) {
    // smarter default: if the image's aspect ratio is wildly mismatched
    // from the card, fit the whole width/height in view instead of
    // aggressively cropping via cover-fit at zoom 1
    if (!img) return 1;
    const ir = img.width / img.height;
    const cr = W / H;
    const mismatch = Math.max(ir / cr, cr / ir);
    if (mismatch > 1.4) return 0.65;
    return 1;
  }

  function getCoverTransform(i) {
    if (!coverTransforms[i]) {
      coverTransforms[i] = { zoom: defaultCoverZoom(loadedCovers[i]), offsetX: 0, offsetY: 0 };
    }
    return coverTransforms[i];
  }

  function genSerial() {
    const n = () => Math.floor(Math.random() * 10);
    return `CF-${n()}${n()}${n()}-${n()}${n()}${n()}${n()}`;
  }

  function loadImage(src) {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = src;
    });
  }

  // ---------- draw helpers ----------
  function drawCoverBg(img, zoom, offsetX, offsetY) {
    const cw = W, ch = H;
    const ir = img.width / img.height;
    const cr = cw / ch;
    let baseW, baseH;
    if (ir > cr) { baseH = ch; baseW = ch * ir; }
    else { baseW = cw; baseH = cw / ir; }

    if (zoom >= 1) {
      // normal case: zoom in from cover-fit, pan within bounds
      const dw = baseW * zoom;
      const dh = baseH * zoom;
      const maxOffX = Math.max(0, (dw - cw) / 2);
      const maxOffY = Math.max(0, (dh - ch) / 2);
      const dx = (cw - dw) / 2 + offsetX * maxOffX;
      const dy = (ch - dh) / 2 + offsetY * maxOffY;
      ctx.drawImage(img, dx, dy, dw, dh);
    } else {
      // zoom < 1: "fit inside" rather than crop — shrink the image below
      // cover-fit and letterbox the gaps with a blurred/dark fill instead
      // of leaving empty space
      ctx.save();
      ctx.filter = 'blur(28px) brightness(0.45)';
      const bleed = 1.15; // slightly oversize the blurred fill so the blur edge doesn't show
      const bw = baseW * bleed, bh = baseH * bleed;
      ctx.drawImage(img, (cw - bw) / 2, (ch - bh) / 2, bw, bh);
      ctx.restore();

      const dw = baseW * zoom;
      const dh = baseH * zoom;
      const maxOffX = Math.max(0, (cw - dw) / 2);
      const maxOffY = Math.max(0, (ch - dh) / 2);
      const dx = (cw - dw) / 2 + offsetX * maxOffX;
      const dy = (ch - dh) / 2 + offsetY * maxOffY;
      ctx.drawImage(img, dx, dy, dw, dh);
    }
  }

  function roundRect(x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }

  function render() {
    ctx.clearRect(0, 0, W, H);

    // base card corner clip
    ctx.save();
    roundRect(0, 0, W, H, 28);
    ctx.clip();

    // background cover art
    if (state.coverImg) {
      drawCoverBg(state.coverImg, state.coverZoom, state.coverOffsetX, state.coverOffsetY);
    } else {
      ctx.fillStyle = '#1a1a1a';
      ctx.fillRect(0, 0, W, H);
    }

    // left-to-right gradient panel so photo+data stay legible over any cover
    const grad = ctx.createLinearGradient(0, 0, W * 0.72, 0);
    grad.addColorStop(0, 'rgba(10,9,8,0.88)');
    grad.addColorStop(0.62, 'rgba(10,9,8,0.55)');
    grad.addColorStop(1, 'rgba(10,9,8,0.08)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, W, H);

    // bottom strip gradient for signature/barcode legibility across full width
    const bottomGrad = ctx.createLinearGradient(0, H * 0.72, 0, H);
    bottomGrad.addColorStop(0, 'rgba(10,9,8,0)');
    bottomGrad.addColorStop(1, 'rgba(10,9,8,0.65)');
    ctx.fillStyle = bottomGrad;
    ctx.fillRect(0, H * 0.7, W, H * 0.3);

    const M = 68; // outer margin

    // helper: state.textColor (hex) at a given alpha, for consistent theming
    function ink(alpha) {
      const hex = state.textColor.replace('#', '');
      const r = parseInt(hex.substring(0, 2), 16);
      const g = parseInt(hex.substring(2, 4), 16);
      const b = parseInt(hex.substring(4, 6), 16);
      return `rgba(${r},${g},${b},${alpha})`;
    }

    // header text, top-left
    ctx.fillStyle = ink(1);
    ctx.textBaseline = 'top';
    ctx.font = '600 72px "Space Grotesk", sans-serif';
    ctx.fillText('PASSPORT', M, M - 8);
    ctx.font = '500 32px "JetBrains Mono", monospace';
    ctx.fillStyle = ink(0.78);
    ctx.fillText('ALBUM IDENTIFICATION CARD', M, M + 70);

    // serial, top right
    ctx.textAlign = 'right';
    ctx.font = '500 32px "JetBrains Mono", monospace';
    ctx.fillStyle = ink(0.9);
    ctx.fillText(state.serial, W - M, M);
    ctx.textAlign = 'left';

    // photo frame — left side, portrait-ish, sized for landscape card
    const pw = 470, ph = 545;
    const px = M, py = M + 132;
    ctx.save();
    ctx.strokeStyle = ink(0.9);
    ctx.lineWidth = 5;
    roundRect(px, py, pw, ph, 18);
    ctx.stroke();
    ctx.clip();
    ctx.fillStyle = 'rgba(255,255,255,0.08)';
    ctx.fillRect(px, py, pw, ph);
    if (state.photoImg) {
      const img = state.photoImg;
      const ir = img.width / img.height;
      const fr = pw / ph;
      // base "cover fit" size, then apply user zoom on top
      let baseW, baseH;
      if (ir > fr) { baseH = ph; baseW = ph * ir; }
      else { baseW = pw; baseH = pw / ir; }
      const dw = baseW * state.photoZoom;
      const dh = baseH * state.photoZoom;
      // offsets are normalized -1..1 range representing how far the image can pan
      const maxOffX = Math.max(0, (dw - pw) / 2);
      const maxOffY = Math.max(0, (dh - ph) / 2);
      const dx = px - (dw - pw) / 2 + state.photoOffsetX * maxOffX;
      const dy = py - (dh - ph) / 2 + state.photoOffsetY * maxOffY;
      ctx.drawImage(img, dx, dy, dw, dh);
    } else {
      ctx.fillStyle = ink(0.4);
      ctx.font = '500 30px "JetBrains Mono", monospace';
      ctx.textAlign = 'center';
      ctx.fillText('PHOTO', px + pw / 2, py + ph / 2 - 16);
      ctx.fillText('NOT PROVIDED', px + pw / 2, py + ph / 2 + 22);
      ctx.textAlign = 'left';
    }
    ctx.restore();

    // data fields — to the right of photo, stacked
    const dataX = px + pw + 64;
    const dataTop = py + 8;
    const lineGap = 148;

    function field(label, value, y) {
      ctx.fillStyle = ink(0.6);
      ctx.font = '700 26px "JetBrains Mono", monospace';
      ctx.fillText(label, dataX, y);
      ctx.fillStyle = ink(0.98);
      ctx.font = '600 66px "Caveat", cursive';
      ctx.fillText(value || '—', dataX, y + 42);
    }

    field('NAME', state.name, dataTop);
    field('DATE OF BIRTH', state.dob, dataTop + lineGap);
    field('LOCATION', state.loc, dataTop + lineGap * 2);

    // signature — bottom left, under photo
    // Underline sits at a fixed baseline; the cursive signature is drawn *above* it and
    // clipped to that baseline so long/tall glyphs never bleed into the SIGNATURE label
    // below. The label itself gets its own reserved row underneath.
    const sigLineY = py + ph + 66;
    ctx.save();
    ctx.beginPath();
    ctx.rect(px, sigLineY - 74, pw, 74); // clip region above the underline
    ctx.clip();
    ctx.fillStyle = ink(0.98);
    ctx.font = '600 60px "Caveat", cursive';
    ctx.fillText(state.sig || 'sign here', px, sigLineY - 14);
    ctx.restore();
    ctx.strokeStyle = ink(0.55);
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(px, sigLineY);
    ctx.lineTo(px + pw, sigLineY);
    ctx.stroke();
    ctx.fillStyle = ink(0.6);
    ctx.font = '700 24px "JetBrains Mono", monospace';
    ctx.fillText('SIGNATURE', px, sigLineY + 34);

    // barcode-ish strip — bottom right area
    const barW = 460, barH = 62;
    const barX = W - M - barW, barY = H - M - barH;
    ctx.save();
    ctx.translate(barX, barY);
    let bx = 0;
    const seedStr = state.serial + state.name;
    for (let i = 0; i < seedStr.length; i++) {
      const c = seedStr.charCodeAt(i);
      const w = (c % 3) + 2;
      if (i % 2 === 0) {
        ctx.fillStyle = ink(0.85);
        ctx.fillRect(bx, 0, w, barH);
      }
      bx += w + 4;
      if (bx > barW) break;
    }
    ctx.restore();
    ctx.textAlign = 'right';
    ctx.fillStyle = ink(0.6);
    ctx.font = '500 22px "JetBrains Mono", monospace';
    ctx.fillText('VALID WORLDWIDE · FAN-MADE', W - M, H - M - barH - 20);
    ctx.textAlign = 'left';

    ctx.restore(); // end clip

    // outer border stroke on top
    ctx.strokeStyle = 'rgba(20,19,17,0.15)';
    ctx.lineWidth = 3;
    roundRect(2, 2, W - 4, H - 4, 60);
    ctx.stroke();
  }

  // ---------- cover swatches ----------
  const swatchWrap = document.getElementById('swatches');

  async function initCovers() {
    for (let i = 0; i < covers.length; i++) {
      try {
        const img = await loadImage(covers[i]);
        loadedCovers[i] = img;
      } catch (e) { console.warn('cover failed to load', i, e); }
      const el = document.createElement('div');
      el.className = 'swatch' + (i === 0 ? ' active' : '');
      el.style.backgroundImage = `url("${covers[i]}")`;
      el.dataset.index = i;
      el.addEventListener('click', () => selectCover(i));
      swatchWrap.appendChild(el);
    }
    // upload-your-own swatch
    const uploadEl = document.createElement('label');
    uploadEl.className = 'swatch upload';
    uploadEl.innerHTML = '+<input type="file" accept="image/*" id="coverUploadInput">';
    swatchWrap.appendChild(uploadEl);

    document.getElementById('coverUploadInput').addEventListener('change', async (e) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = async (ev) => {
        const img = await loadImage(ev.target.result);
        const idx = loadedCovers.length;
        loadedCovers[idx] = img;
        const el = document.createElement('div');
        el.className = 'swatch';
        el.style.backgroundImage = `url("${ev.target.result}")`;
        el.dataset.index = idx;
        el.addEventListener('click', () => selectCover(idx));
        swatchWrap.insertBefore(el, uploadEl);
        selectCover(idx);
      };
      reader.readAsDataURL(file);
    });

    if (loadedCovers[0]) {
      state.coverImg = loadedCovers[0];
      const t = getCoverTransform(0);
      state.coverZoom = t.zoom;
      state.coverOffsetX = t.offsetX;
      state.coverOffsetY = t.offsetY;
      coverZoomSlider.value = Math.round(t.zoom * 100);
      coverPanYSlider.value = Math.round(t.offsetY * 100);
      render();
    }
  }

  function selectCover(i) {
    state.coverIndex = i;
    state.coverImg = loadedCovers[i];
    const t = getCoverTransform(i);
    state.coverZoom = t.zoom;
    state.coverOffsetX = t.offsetX;
    state.coverOffsetY = t.offsetY;
    coverZoomSlider.value = Math.round(t.zoom * 100);
    coverPanYSlider.value = Math.round(t.offsetY * 100);
    document.querySelectorAll('.swatch').forEach(s => {
      s.classList.toggle('active', s.dataset.index == i);
    });
    render();
  }

  // ---------- photo upload ----------
  const dropzone = document.getElementById('dropzone');
  const photoInput = document.getElementById('photoInput');

  function resetPhotoTransform() {
    state.photoZoom = 1;
    state.photoOffsetX = 0;
    state.photoOffsetY = 0;
    zoomSlider.value = 100;
  }

  photoInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      state.photoImg = await loadImage(ev.target.result);
      resetPhotoTransform();
      render();
    };
    reader.readAsDataURL(file);
  });

  ['dragover', 'drop'].forEach(evt => {
    dropzone.addEventListener(evt, (e) => e.preventDefault());
  });
  dropzone.addEventListener('drop', (e) => {
    const file = e.dataTransfer.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async (ev) => {
      state.photoImg = await loadImage(ev.target.result);
      resetPhotoTransform();
      render();
    };
    reader.readAsDataURL(file);
  });

  // ---------- zoom slider + reset ----------
  const zoomSlider = document.getElementById('zoomSlider');
  zoomSlider.addEventListener('input', () => {
    state.photoZoom = zoomSlider.value / 100;
    render();
  });
  document.getElementById('resetPhotoBtn').addEventListener('click', () => {
    resetPhotoTransform();
    render();
  });

  // ---------- cover zoom slider + reset ----------
  const coverZoomSlider = document.getElementById('coverZoomSlider');
  coverZoomSlider.addEventListener('input', () => {
    state.coverZoom = coverZoomSlider.value / 100;
    const t = getCoverTransform(state.coverIndex);
    t.zoom = state.coverZoom;
    render();
  });
  document.getElementById('resetCoverBtn').addEventListener('click', () => {
    state.coverZoom = defaultCoverZoom(state.coverImg);
    state.coverOffsetX = 0;
    state.coverOffsetY = 0;
    coverZoomSlider.value = Math.round(state.coverZoom * 100);
    coverPanYSlider.value = 0;
    coverTransforms[state.coverIndex] = { zoom: state.coverZoom, offsetX: 0, offsetY: 0 };
    render();
  });

  // ---------- cover vertical pan slider ----------
  const coverPanYSlider = document.getElementById('coverPanYSlider');
  coverPanYSlider.addEventListener('input', () => {
    state.coverOffsetY = coverPanYSlider.value / 100;
    const t = getCoverTransform(state.coverIndex);
    t.offsetY = state.coverOffsetY;
    render();
  });

  // ---------- text color ----------
  const TEXT_COLOR_PRESETS = ['#f2efe8', '#141311', '#ff5a36', '#ffd23f', '#6ec6ff', '#ff8fb1'];
  const colorSwatchWrap = document.getElementById('colorSwatches');
  const customColorInput = document.getElementById('customColor');

  function setTextColor(hex) {
    state.textColor = hex;
    document.querySelectorAll('.color-swatch').forEach(s => {
      s.classList.toggle('active', s.dataset.color.toLowerCase() === hex.toLowerCase());
    });
    render();
  }

  TEXT_COLOR_PRESETS.forEach((hex) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'color-swatch' + (hex === state.textColor ? ' active' : '');
    btn.style.background = hex;
    btn.dataset.color = hex;
    btn.title = hex;
    btn.addEventListener('click', () => {
      setTextColor(hex);
      customColorInput.value = hex;
    });
    colorSwatchWrap.appendChild(btn);
  });

  customColorInput.addEventListener('input', () => {
    setTextColor(customColorInput.value);
  });

  // ---------- drag on canvas to pan either the cover bg or the photo ----------
  // photo frame geometry, kept in sync with render()'s values
  const FRAME = { pw: 470, ph: 545, px: 68, py: 68 + 132 };
  let dragging = false;
  let dragTarget = null; // 'photo' | 'cover'
  let dragStart = { x: 0, y: 0, offX: 0, offY: 0 };

  function canvasPointFromEvent(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    return {
      x: (clientX - rect.left) * scaleX,
      y: (clientY - rect.top) * scaleY
    };
  }

  function isInsidePhotoFrame(pt) {
    return pt.x >= FRAME.px && pt.x <= FRAME.px + FRAME.pw &&
           pt.y >= FRAME.py && pt.y <= FRAME.py + FRAME.ph;
  }

  function startDrag(e) {
    if (e.touches && e.touches.length === 2) {
      startPinch(e);
      return;
    }
    const pt = canvasPointFromEvent(e);
    const overPhoto = isInsidePhotoFrame(pt);
    if (overPhoto && state.photoImg) {
      dragTarget = 'photo';
      dragStart = { x: pt.x, y: pt.y, offX: state.photoOffsetX, offY: state.photoOffsetY };
    } else if (!overPhoto && state.coverImg) {
      dragTarget = 'cover';
      dragStart = { x: pt.x, y: pt.y, offX: state.coverOffsetX, offY: state.coverOffsetY };
    } else {
      return;
    }
    dragging = true;
    canvas.classList.add('dragging');
    e.preventDefault();
  }
  function moveDrag(e) {
    if (e.touches && e.touches.length === 2) {
      movePinch(e);
      return;
    }
    if (pinching) return; // one finger lifted mid-pinch — ignore until full release
    if (!dragging) return;
    const pt = canvasPointFromEvent(e);
    const dx = pt.x - dragStart.x;
    const dy = pt.y - dragStart.y;
    if (dragTarget === 'photo') {
      // convert pixel delta to normalized offset relative to frame size
      state.photoOffsetX = clamp(dragStart.offX + dx / (FRAME.pw / 2), -1, 1);
      state.photoOffsetY = clamp(dragStart.offY + dy / (FRAME.ph / 2), -1, 1);
    } else if (dragTarget === 'cover') {
      state.coverOffsetX = clamp(dragStart.offX + dx / (W / 2), -1, 1);
      state.coverOffsetY = clamp(dragStart.offY + dy / (H / 2), -1, 1);
      const t = getCoverTransform(state.coverIndex);
      t.offsetX = state.coverOffsetX;
      t.offsetY = state.coverOffsetY;
      coverPanYSlider.value = Math.round(state.coverOffsetY * 100);
    }
    render();
    e.preventDefault();
  }
  function endDrag(e) {
    if (e && e.touches && e.touches.length > 0) {
      // still one finger down after a pinch — don't restart a drag from it
      pinching = false;
      dragging = false;
      dragTarget = null;
      return;
    }
    dragging = false;
    dragTarget = null;
    pinching = false;
    canvas.classList.remove('dragging');
  }
  function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }

  // ---------- pinch-to-zoom (touch) for cover bg or photo ----------
  let pinching = false;
  let pinchTarget = null; // 'photo' | 'cover'
  let pinchStartDist = 0;
  let pinchStartZoom = 1;

  function touchMidpoint(e) {
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    const t0 = e.touches[0], t1 = e.touches[1];
    return {
      x: ((t0.clientX + t1.clientX) / 2 - rect.left) * scaleX,
      y: ((t0.clientY + t1.clientY) / 2 - rect.top) * scaleY
    };
  }
  function touchDist(e) {
    const dx = e.touches[0].clientX - e.touches[1].clientX;
    const dy = e.touches[0].clientY - e.touches[1].clientY;
    return Math.hypot(dx, dy);
  }
  function startPinch(e) {
    dragging = false;
    const mid = touchMidpoint(e);
    pinchTarget = isInsidePhotoFrame(mid) && state.photoImg ? 'photo' : (state.coverImg ? 'cover' : null);
    if (!pinchTarget) return;
    pinching = true;
    pinchStartDist = touchDist(e);
    pinchStartZoom = pinchTarget === 'photo' ? state.photoZoom : state.coverZoom;
    e.preventDefault();
  }
  function movePinch(e) {
    if (!pinching || !pinchTarget) return;
    const dist = touchDist(e);
    if (pinchStartDist <= 0) return;
    const scale = dist / pinchStartDist;
    if (pinchTarget === 'photo') {
      const z = clamp(pinchStartZoom * scale, 1, 3);
      state.photoZoom = z;
      zoomSlider.value = Math.round(z * 100);
    } else {
      const z = clamp(pinchStartZoom * scale, 0.4, 2.5);
      state.coverZoom = z;
      coverZoomSlider.value = Math.round(z * 100);
      const t = getCoverTransform(state.coverIndex);
      t.zoom = z;
    }
    render();
    e.preventDefault();
  }

  canvas.classList.add('draggable');
  canvas.addEventListener('mousedown', startDrag);
  window.addEventListener('mousemove', moveDrag);
  window.addEventListener('mouseup', endDrag);
  canvas.addEventListener('touchstart', startDrag, { passive: false });
  window.addEventListener('touchmove', moveDrag, { passive: false });
  window.addEventListener('touchend', endDrag);
  window.addEventListener('touchcancel', endDrag);

  // ---------- text fields ----------
  function bindField(id, key) {
    const el = document.getElementById(id);
    el.addEventListener('input', () => {
      state[key] = el.value;
      render();
    });
  }
  bindField('fName', 'name');
  bindField('fDob', 'dob');
  bindField('fLoc', 'loc');
  bindField('fSig', 'sig');

  // ---------- shuffle serial ----------
  document.getElementById('shuffleBtn').addEventListener('click', () => {
    state.serial = genSerial();
    render();
  });

  // ---------- download ----------
  document.getElementById('downloadBtn').addEventListener('click', () => {
    const link = document.createElement('a');
    const safeName = (state.name || 'my-id').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-');
    link.download = `${safeName || 'album-id'}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  });

  // wait for fonts before first paint for crisp text
  if (document.fonts && document.fonts.ready) {
    document.fonts.ready.then(() => { render(); });
  }

  initCovers();
  render();
})();
